class Solution {
    void dfs(int key, int currentSum, unordered_map<int, int>& tree, int& totalSum) {
        if (!tree.count(key)) return;
        currentSum += tree[key];
        int d = key / 10;
        int p = key % 10;
        int left = (d + 1) * 10 + (2 * p - 1);
        int right = (d + 1) * 10 + (2 * p);

        if (!tree.count(left) && !tree.count(right)) {
            totalSum += currentSum;
            return;
        }
        if (tree.count(left)) dfs(left, currentSum, tree, totalSum);
        if (tree.count(right)) dfs(right, currentSum, tree, totalSum);
    }
public:
