class Solution {
    private int totalSum = 0;

    public int pathSum(int[] nums) {
        Map<Integer, Integer> tree = new HashMap<>();
        for (int num : nums) {
            tree.put(num / 10, num % 10);
        }
        dfs(11, 0, tree);
        return totalSum;
    }

    private void dfs(int key, int currentSum, Map<Integer, Integer> tree) {
        if (!tree.containsKey(key)) return;
        currentSum += tree.get(key);
        int d = key / 10;
        int p = key % 10;
        int left = (d + 1) * 10 + (2 * p - 1);
        int right = (d + 1) * 10 + (2 * p);

        if (!tree.containsKey(left) && !tree.containsKey(right)) {
            totalSum += currentSum;
            return;
        }
        if (tree.containsKey(left)) dfs(left, currentSum, tree);
        if (tree.containsKey(right)) dfs(right, currentSum, tree);
    }
}

var pathSum = function(nums) {
    const tree = new Map();
    for (const num of nums) {
        tree.set(Math.floor(num / 10), num % 10);
    }

    let totalSum = 0;

    function dfs(key, currentSum) {
        if (!tree.has(key)) return;
        currentSum += tree.get(key);
        const d = Math.floor(key / 10);
        const p = key % 10;
        const left = (d + 1) * 10 + (2 * p - 1);
        const right = (d + 1) * 10 + (2 * p);

        if (!tree.has(left) && !tree.has(right)) {
            totalSum += currentSum;
            return;
        }
        if (tree.has(left)) dfs(left, currentSum);
        if (tree.has(right)) dfs(right, currentSum);
    }

    dfs(11, 0);
    return totalSum;
};
